# ──────────────────────────────────────────────────────────────────────────────
# Utilities
# ──────────────────────────────────────────────────────────────────────────────

def clamp(v: float, lo: float, hi: float) -> float:
    return max(lo, min(hi, v))

def angle_wrap(a: float) -> float:
    while a >  math.pi: a -= 2 * math.pi
    while a < -math.pi: a += 2 * math.pi
    return a

class EMA:
    def __init__(self, alpha: float = 0.25):
        self.alpha = alpha; self._v = None
    def update(self, x: float) -> float:
        self._v = x if self._v is None else self.alpha * x + (1 - self.alpha) * self._v
        return self._v

# ──────────────────────────────────────────────────────────────────────────────
# Occupancy grid
# ──────────────────────────────────────────────────────────────────────────────

class OccupancyGrid:
    def __init__(self, res: float):
        self.res = res
        self.logodds: dict[tuple[int, int], float] = defaultdict(float)
        self._version = 0
        self._occ_cache = 0; self._occ_cache_version = -1

    def world_to_cell(self, x: float, y: float) -> tuple[int, int]:
        return (int(round(x / self.res)), int(round(y / self.res)))

    def cell_to_world(self, cell: tuple[int, int]) -> tuple[float, float]:
        return cell[0] * self.res, cell[1] * self.res

    def occupied_count_cached(self) -> int:
        if self._version != self._occ_cache_version:
            self._occ_cache = sum(1 for lo in self.logodds.values() if lo >= OCC_THRESHOLD)
            self._occ_cache_version = self._version
        return self._occ_cache

    def _add_lo(self, cell, delta: float):
        self.logodds[cell] = clamp(self.logodds[cell] + delta, LOG_MIN, LOG_MAX)

    @staticmethod
    def _bresenham(x0, y0, x1, y1) -> list[tuple[int, int]]:
        pts = []; dx, sx = abs(x1 - x0), 1 if x0 < x1 else -1
        dy, sy = -abs(y1 - y0), 1 if y0 < y1 else -1
        err = dx + dy
        while True:
            pts.append((x0, y0))
            if x0 == x1 and y0 == y1: break
            e2 = 2 * err
            if e2 >= dy: err += dy; x0 += sx
            if e2 <= dx: err += dx; y0 += sy
        return pts

    def update_with_scan(self, rx: float, ry: float, yaw: float, ranges: list[float], fov: float, step: int, is_reversed: bool):
        if not ranges: return
        n = len(ranges); angle_min = -fov / 2.0
        robot_cell = self.world_to_cell(rx, ry)
        changed = False

        for i in range(0, n, step):
            idx = (n - 1 - i) if is_reversed else i
            r = ranges[idx]
            if not math.isfinite(r) or r < LIDAR_MIN_RANGE: continue

            beam_angle = yaw + LIDAR_YAW_OFFSET + angle_min + (i / max(1, n - 1)) * fov
            is_hit = r < (LIDAR_MAX_RANGE - 0.05)
            r_use  = min(r, LIDAR_MAX_RANGE)

            ex, ey = rx + r_use * math.cos(beam_angle), ry + r_use * math.sin(beam_angle)
            end_cell = self.world_to_cell(ex, ey)
            ray = self._bresenham(robot_cell[0], robot_cell[1], end_cell[0], end_cell[1])
            if len(ray) <= 1: continue

            for cell in (ray[:-1] if is_hit else ray): self._add_lo(cell, LOG_FREE)
            if is_hit: self._add_lo(ray[-1], LOG_HIT)
            changed = True

        if changed:
            self._version += 1

# ──────────────────────────────────────────────────────────────────────────────
# Correlative scan matcher
# ──────────────────────────────────────────────────────────────────────────────

class CorrelativeScanMatcher:
    def __init__(self, grid: OccupancyGrid):
        self.grid = grid
        self._dx = list(self._arange(-SEARCH_XY_RANGE, SEARCH_XY_RANGE, SEARCH_XY_STEP))
        self._dy = list(self._arange(-SEARCH_XY_RANGE, SEARCH_XY_RANGE, SEARCH_XY_STEP))
        self._dt = list(self._arange(-SEARCH_THETA_RANGE, SEARCH_THETA_RANGE, SEARCH_THETA_STEP))
        self._score_table = None; self._score_table_version = -1

    @staticmethod
    def _arange(start, stop, step):
        v = start
        while v <= stop + 1e-9: yield v; v += step

    def extract_points(self, ranges: list[float], fov: float, step: int, is_reversed: bool) -> "np.ndarray | None":
        if not NP_AVAILABLE or not ranges: return None
        n = len(ranges); indices = np.arange(0, n, step, dtype=np.int32)
        beam_idx = (n - 1 - indices) if is_reversed else indices
        r = np.asarray(ranges, dtype=np.float64)[beam_idx]

        valid = np.isfinite(r) & (r >= LIDAR_MIN_RANGE) & (r <= LIDAR_MAX_RANGE)
        r, frac = r[valid], indices[valid] / max(1, n - 1)
        if len(r) < 5: return None

        angs = (-fov / 2.0) + frac * fov
        return np.column_stack([r * np.cos(angs), r * np.sin(angs)]).astype(np.float64)

    def _build_score_table(self):
        if self._score_table is not None and self.grid._version == self._score_table_version:
            return self._score_table, self._score_table_ox, self._score_table_oy
        if not self.grid.logodds: return None, 0, 0

        cells = list(self.grid.logodds.items())
        ixs = np.array([c[0][0] for c in cells], dtype=np.int32)
        iys = np.array([c[0][1] for c in cells], dtype=np.int32)
        los = np.array([c[1]    for c in cells], dtype=np.float32)

        scores = np.where(los >= OCC_THRESHOLD, 3.0, np.where(los <= FREE_THRESHOLD, -0.8, -0.1)).astype(np.float32)
        ox, oy = int(ixs.min()), int(iys.min())
        w, h = int(ixs.max()) - ox + 1, int(iys.max()) - oy + 1
        table = np.full((w, h), -0.1, dtype=np.float32)
        table[ixs - ox, iys - oy] = scores

        self._score_table, self._score_table_ox, self._score_table_oy, self._score_table_version = table, ox, oy, self.grid._version
        return table, ox, oy

    def match(self, pred_x: float, pred_y: float, pred_yaw: float, local_pts: "np.ndarray | None") -> tuple[float, float, float, bool]:
        if not SCAN_MATCH_ENABLED or local_pts is None: return pred_x, pred_y, pred_yaw, False
        if len(local_pts) < SCAN_MATCH_MIN_POINTS: return pred_x, pred_y, pred_yaw, False
        if self.grid.occupied_count_cached() < SCAN_MATCH_MIN_OCC_CELLS: return pred_x, pred_y, pred_yaw, False

        table, tox, toy = self._build_score_table()
        if table is None: return pred_x, pred_y, pred_yaw, False

        tw, th, res = table.shape[0], table.shape[1], self.grid.res
        best_score, best_x, best_y, best_yaw = -1e18, pred_x, pred_y, pred_yaw

        for dth in self._dt:
            candidate_yaw = angle_wrap(pred_yaw + dth)
            c, s = math.cos(candidate_yaw), math.sin(candidate_yaw)
            rx, ry = c * local_pts[:, 0] - s * local_pts[:, 1], s * local_pts[:, 0] + c * local_pts[:, 1]

            for dx in self._dx:
                wx = pred_x + dx
                for dy in self._dy:
                    wy = pred_y + dy
                    ix, iy = np.round((wx + rx) / res).astype(np.int32) - tox, np.round((wy + ry) / res).astype(np.int32) - toy
                    valid = (ix >= 0) & (ix < tw) & (iy >= 0) & (iy < th)
                    if not valid.any(): continue
                    score = float(table[ix[valid], iy[valid]].sum()) - 0.1 * int((~valid).sum())
                    score -= MATCH_PRIOR_LAMBDA * (dx * dx + dy * dy + (MATCH_PRIOR_YAW_K * dth) ** 2)
                    if score > best_score:
                        best_score, best_x, best_y, best_yaw = score, wx, wy, candidate_yaw

        if best_score <= -1e17:
            return pred_x, pred_y, pred_yaw, False

        return pred_x + BLEND_POS * (best_x - pred_x), pred_y + BLEND_POS * (best_y - pred_y), angle_wrap(pred_yaw + BLEND_YAW * angle_wrap(best_yaw - pred_yaw)), True

