class MappingController:
    def __init__(self):
        self.robot      = Robot()
        self.timestep   = int(self.robot.getBasicTimeStep())
        self.dt         = self.timestep / 1000.0
        self.time_sec   = 0.0

        self.keyboard     = Keyboard()
        self.keyboard.enable(self.timestep)

        self.camera       = self._init_camera()
        self.lidar        = self._init_lidar()

        self.depth        = self._init_depth()
        self.rgb          = self._init_rgb()

        if self.depth and not NP_AVAILABLE:
            self.depth = None

        if self.depth:
            self.depth_w, self.depth_h = self.depth.getWidth(), self.depth.getHeight()
            self.depth_fov = self.depth.getFov()

            cx = self.depth_w / 2.0
            cy = self.depth_h / 2.0
            fx = cx / math.tan(self.depth_fov * 0.5)
            fy = fx

            self.depth_fov_v = 2.0 * math.atan(math.tan(self.depth_fov * 0.5) * self.depth_h / self.depth_w)

            us = np.arange(0, self.depth_w, DEPTH_PIXEL_STEP, dtype=np.float32)
            vs = np.arange(0, self.depth_h, DEPTH_PIXEL_STEP, dtype=np.float32)

            self._ray_y_left = (cx - us) / fx
            self._ray_z_up = (cy - vs) / fy

        self.gps          = self._try_get(self.robot.getDevice, ["gps", "GPS"])
        self.compass      = self._try_get(self.robot.getDevice, ["compass", "Compass"])
        self.compass_diag = self.compass or self._try_get(self.robot.getDevice, ["imu compass"])
        self.imu          = self._try_get(self.robot.getDevice, ["imu inertial_unit", "inertial unit", "inertial_unit", "IMU", "imu"])
        self.gyro         = self._try_get(self.robot.getDevice, ["imu gyro", "gyro", "Gyro"])
        self.accelerometer = self._try_get(self.robot.getDevice, ["imu accelerometer", "accelerometer", "Accelerometer"])

        self.wheels       = self._init_wheels()
        self.wheel_enc    = self._init_encoders()

        self.x, self.y, self.yaw = 0.0, 0.0, 0.0
        self._odom_yaw = 0.0
        self.cmd_linear, self.cmd_angular = 0.0, 0.0
        self._enc_left_prev, self._enc_right_prev = None, None
        self._last_map_x, self._last_map_y, self._last_map_yaw = 0.0, 0.0, 0.0
